<?php require_once '../config/config.php';$u=require_admin();$title='Admin Dashboard | '.APP_NAME;
$stats=['rooms'=>(int)db()->query("SELECT COUNT(*) FROM rooms")->fetchColumn(),'bookings'=>(int)db()->query("SELECT COUNT(*) FROM bookings")->fetchColumn(),'customers'=>(int)db()->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),'revenue'=>(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='paid'")->fetchColumn()];
$recent=db()->query("SELECT b.*,u.name,r.room_number,rt.name type_name,p.status payment_status FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id JOIN room_types rt ON rt.id=r.room_type_id LEFT JOIN payments p ON p.booking_id=b.id ORDER BY b.created_at DESC LIMIT 10")->fetchAll();
require '../partials_header.php';?>
<div class="admin-nav"><div class="container"><strong>Admin Panel</strong><a href="index.php">Dashboard</a><a href="rooms.php">Rooms</a><a href="bookings.php">Bookings</a></div></div>
<div class="page"><div class="container"><h1>Dashboard</h1><div class="stats"><?php foreach([['Rooms',$stats['rooms']],['Bookings',$stats['bookings']],['Customers',$stats['customers']],['Revenue','NPR '.number_format($stats['revenue'])]] as $x): ?><div class="stat"><span class="muted"><?=$x[0]?></span><br><strong><?=e((string)$x[1])?></strong></div><?php endforeach;?></div><br><div class="panel table-wrap"><h2>Recent Bookings</h2><table class="table"><tr><th>Code</th><th>Guest</th><th>Room</th><th>Dates</th><th>Amount</th><th>Status</th></tr><?php foreach($recent as $b): ?><tr><td><?=e($b['booking_code'])?></td><td><?=e($b['name'])?></td><td><?=e($b['type_name'])?> #<?=e($b['room_number'])?></td><td><?=e($b['check_in'])?> → <?=e($b['check_out'])?></td><td>NPR <?=number_format((float)$b['total_amount'])?></td><td><span class="badge <?=e($b['status'])?>"><?=e($b['status'])?></span></td></tr><?php endforeach;?></table></div></div></div><?php require '../partials_footer.php'; ?>
